clc;
clear;
close all;

% Parameter for all three systems (stable if |a| < 1)
a = 0.8;

% Frequency grid
N = 100;
w = linspace(0, pi, N).';
q = exp(-1j*w);   % q = z^-1 on the unit circle

% H1(z): Low-pass filter
b1 = 1 - a;
a1 = [1 -a];

% H2(z): High-pass filter
b2 = [(1 + a)/2, -(1 + a)/2];
a2 = [1 -a];

% H3(z): All-pass filter
b3 = [a 1];
a3 = [1 a];

% Frequency responses
H1 = polyval(fliplr(b1), q) ./ polyval(fliplr(a1), q);
H2 = polyval(fliplr(b2), q) ./ polyval(fliplr(a2), q);
H3 = polyval(fliplr(b3), q) ./ polyval(fliplr(a3), q);

f = w / pi;   % Normalized frequency (0 to 1)

% Plot magnitude and phase
figure; %[output:6569739c]

subplot(3,2,1); %[output:6569739c]
plot(f, abs(H1), 'LineWidth', 1.5); %[output:6569739c]
grid on; %[output:6569739c]
title('LPF H_1(z) Magnitude'); %[output:6569739c]
xlabel('Normalized Frequency (\times\pi rad/sample)'); %[output:6569739c]
ylabel('|H_1|'); %[output:6569739c]

subplot(3,2,2); %[output:6569739c]
plot(f, unwrap(angle(H1)), 'LineWidth', 1.5); %[output:6569739c]
grid on; %[output:6569739c]
title('LPF H_1(z) Phase'); %[output:6569739c]
xlabel('Normalized Frequency (\times\pi rad/sample)'); %[output:6569739c]
ylabel('Phase (rad)'); %[output:6569739c]

subplot(3,2,3); %[output:6569739c]
plot(f, abs(H2), 'LineWidth', 1.5); %[output:6569739c]
grid on; %[output:6569739c]
title('HPF H_2(z) Magnitude'); %[output:6569739c]
xlabel('Normalized Frequency (\times\pi rad/sample)'); %[output:6569739c]
ylabel('|H_2|'); %[output:6569739c]

subplot(3,2,4); %[output:6569739c]
plot(f, unwrap(angle(H2)), 'LineWidth', 1.5); %[output:6569739c]
grid on; %[output:6569739c]
title('HPF H_2(z) Phase'); %[output:6569739c]
xlabel('Normalized Frequency (\times\pi rad/sample)'); %[output:6569739c]
ylabel('Phase (rad)'); %[output:6569739c]

subplot(3,2,5); %[output:6569739c]
plot(f, abs(H3), 'LineWidth', 1.5); %[output:6569739c]
grid on; %[output:6569739c]
title('All-pass H_3(z) Magnitude'); %[output:6569739c]
xlabel('Normalized Frequency (\times\pi rad/sample)'); %[output:6569739c]
ylabel('|H_3|'); %[output:6569739c]

subplot(3,2,6); %[output:6569739c]
plot(f, unwrap(angle(H3)), 'LineWidth', 1.5); %[output:6569739c]
grid on; %[output:6569739c]
title('All-pass H_3(z) Phase'); %[output:6569739c]
xlabel('Normalized Frequency (\times\pi rad/sample)'); %[output:6569739c]
ylabel('Phase (rad)'); %[output:6569739c]


